contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable {
        require(amount <= address(c).balance);

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;

        c.withdraw(amount); if (__ESBMC_reverted()) return;

        assert(c.owner() == ownerBefore && c.depositsCount() == depositsBefore && address(c).balance == balanceBefore - amount);
    }

    receive() external payable {}
}

